015", "content_type": "REAL_LIFE_CHALLENGE", "domain": "LEAD", "skill": "Advocacy / systems thinking", "difficulty": "Hard", "xp_value": "+15", "related_quick_learn_id": "QL_015", "related_practice_id": "PRACTICE_028", "source_type": "behavioral_extension", "review_status": "expert_review", "expert_reviewed": "false", "medical_review_required": "false", "content_version": "1.0", "active": "true", "title": "Make One Thing More Inclusive", "instruction": "Notice one small change that could make a real setting more inclusive for someone with celiac disease.", "safety_note": "Completing the challenge does not require the other person or organization to make the change. Noticing, proposing, or discussing a constructive idea counts.", "completion_message": "You tried the skill. That counts. +15 XP", "source_basis": "Meyer & Naveh self-management framework; teen advocacy extension", "steps": ["Maybe school events could share food information earlier.", "Maybe a club could keep packaged options available.", "Maybe friends could choose restaurants together instead of leaving all the research to one person.", "If you want to, suggest the change to someone who could help."], "reflection_options": ["😊 Easier than expected", "🙂 Pretty good", "😐 Okay", "😬 Awkward", "🔄 Didn't go as planned"], "source_url": "https://doi.org/10.3390/nu13051401", "review_note": "Keep this challenge flagged for expert review before public release. It translates evidence and/or teen lived experience into a real-world self-management activity."}}, "choices": [], "feedback": {}, "teaching_point": null, "next_step": null, "related_content_ids": ["59f84298-c5d8-5f4d-8e00-e00b714e48e8", "cbfd3d5a-c688-5b19-b455-700abf875fe2"], "xp_value": 15, "source_type": "EDITORIAL", "source_organization": "Meyer & Naveh self-management framework; teen advocacy extension", "source_title": null, "source_url": "https://doi.org/10.3390/nu13051401", "author": null, "review_status": "IN_REVIEW", "expert_reviewer": null, "medical_review_required": false, "content_version": 1, "last_reviewed": null, "active": true}]$records$::jsonb)), checked as (
select x.record->'content_body'->>'challenge_id' as challenge_id,e.content_id,
not exists(select 1 from jsonb_each(x.record) f where to_jsonb(e)->f.key is distinct from f.value) as matches
from expected x left join public.explore_content e on e.content_id::text=x.record->>'content_id' or e.content_body->>'challenge_id'=x.record->'content_body'->>'challenge_id')
select challenge_id,count(content_id) as record_count,case when count(content_id)=1 and bool_and(matches) then 'PASS' else 'CHECK MISSING, DUPLICATE, OR CHANGED FIELDS' end as qa_result from checked group by challenge_id order by challenge_id;
